// One-inner numerical comparison on a complete saved physical/source objective.
#include "rinkfit/joint_seed_inner.hpp"
#include "rinkfit/joint_source_guard.hpp"
#include <fstream>
#include <iostream>
using namespace rinkfit;

static eventio::Json compact_constraints(JointALBuilder&b,const StateSnapshot&s,const OuterState&o){auto vals=b.evaluate_constraints(s);const auto&sc=b.schema();eventio::Json groups=eventio::Json::object();double total=0;auto add=[&](const std::string&id,double raw,bool eq,double dual){std::string key;if(eq)key=id.rfind("RS/",0)==0?"RS":id.rfind("frozen_query_0/",0)==0?"frozen_query_0":id.rfind("frozen_query_1/",0)==0?"frozen_query_1":"physical_equality";else key=id.rfind("pixel/",0)==0?"pixel":id.rfind("native_domain/",0)==0?"native_domain_"+id.substr(id.find_last_of('/')+1):id.find("whole_cubic_hull")!=std::string::npos?"whole_zoom_hull":id.find("whole_zoom_Brown")!=std::string::npos?"whole_zoom_Brown":"finite_physical";auto&g=groups[key];if(g.is_null())g={{"count",0},{"max_violation",0.},{"sum_absolute_or_positive_violation",0.},{"PHR_half_cost",0.}};double violation=eq?std::abs(raw):std::max(0.,raw),r=eq?equality_residual(raw,dual,o.rho):inequality_residual(raw,dual,o.rho);g["count"]=g["count"].get<std::size_t>()+1;g["max_violation"]=std::max(g["max_violation"].get<double>(),violation);g["sum_absolute_or_positive_violation"]=g["sum_absolute_or_positive_violation"].get<double>()+violation;g["PHR_half_cost"]=g["PHR_half_cost"].get<double>()+.5*r*r;total+=.5*r*r;};for(std::size_t i=0;i<vals.g.size();++i)add(sc.inequality_ids[i],vals.g[i],false,o.lambda[i]);for(std::size_t i=0;i<vals.h.size();++i)add(sc.equality_ids[i],vals.h[i],true,o.nu[i]);double budget=*b.budget_parameter();if(o.phase==Phase::kFeasibility){double r=phase_one_budget_residual(budget);total+=.5*r*r;}return {{"state_token",s.token()},{"groups",groups},{"budget_sq",budget},{"double_PHR_half_cost",total},{"canonical_AD_merit_or_formal_certificate",false}};}
int main(int argc,char**argv){try{if(argc!=8)throw std::runtime_error("MODEL PACKET CHECKPOINT PTX OUT LINE_STEPS RADIUS");std::filesystem::path out=argv[5];if(std::filesystem::exists(out))throw std::runtime_error("immutable probe exists");std::filesystem::create_directories(out);auto model=JointEventModel::load(argv[1]);auto packet=JointPacket::load(argv[2],model);const auto guard=joint_source_guard_snapshot(packet.source_json);if(!joint_source_recall_marker(guard,argv[2],true).empty())throw std::runtime_error("recalled source");std::ifstream f(argv[3]);auto checkpoint=read_checkpoint(f);JointALBuilder b(std::move(model),std::move(packet),false,false);b.restore_state(checkpoint.state);if(b.capture_state().token()!=checkpoint.state.token())throw std::runtime_error("actual checkpoint failed exact roundtrip");const int line_steps=std::stoi(argv[6]);const double radius=std::stod(argv[7]);RuntimeLimits limits;limits.max_inner_iterations=1;limits.num_threads=12;limits.log_ceres_progress=true;limits.inequality_kink_active=true;ObjectiveContext context{checkpoint.outer.phase,checkpoint.outer.lambda,checkpoint.outer.nu,checkpoint.outer.rho,"same_complete_saved_objective/"+checkpoint.state.token(),true};b.enable_gpu_raw_uv(argv[4],12,out/"gpu_cache.jsonl");RunHooks hooks;eventio::Json records=eventio::Json::array(),timing;hooks.on_iteration=[&](const StateSnapshot&,const OuterState&,const IterationRecord&i){records.push_back({{"iteration",i.iteration},{"accepted",i.step_accepted},{"cost",i.inner_cost},{"actual_cost_change",i.actual_cost_change},{"relative_decrease",i.relative_decrease},{"trust_region_radius",i.trust_region_radius},{"iteration_seconds",i.iteration_time_in_seconds},{"linear_solver_seconds",i.step_solver_time_in_seconds}});std::ofstream log(out/"iterations.json");log<<records.dump(2);};hooks.on_solver_summary=[&](const OuterState&,const std::string&,const std::map<std::string,double>&t){timing=t;};hooks.stop_requested=[&](){return !joint_source_recall_marker(guard,argv[2]).empty();};std::ofstream before(out/"before_constraints.json");before<<compact_constraints(b,checkpoint.state,checkpoint.outer).dump(2);before.close();JointGeometrySeedInner inner(radius,line_steps);auto result=inner.solve(b,context,checkpoint.outer,limits,hooks,1e9);b.restore_state(result.accepted_state);const auto current=b.capture_state();std::ofstream after(out/"after_constraints.json");after<<compact_constraints(b,current,checkpoint.outer).dump(2);after.close();eventio::Json numerical_aux=eventio::Json::object();for(const auto&parameter:current.data().parameters)if(parameter.name=="budget_sq"||parameter.name.find("/numerical_zoom_enclosure")!=std::string::npos)numerical_aux[parameter.name]=parameter.values;std::ofstream an(out/"numerical_auxiliary_state.json");an<<numerical_aux.dump(2);an.close();std::ofstream mf(out/"model.json");mf<<b.core.model.json().dump(2);mf.close();b.export_explicit_nuisance(out/"explicit_nuisance");std::ofstream receipt(out/"accepted_state_receipt.json");receipt<<eventio::Json({{"schema","rinkfit.joint_PHR_accepted_numerical_iterate.v1"},{"state_token",current.token()},{"source_packet",argv[2]},{"source_packet_sha256",b.core.packet.source_hash},{"model_sha256",eventio::file_sha256(out/"model.json")},{"complete_physical_and_explicit_nuisance_state",true},{"AL_dual_resume_checkpoint",false},{"native_RS_pixel_physical_audit_pass_claimed",false},{"joint_fit_complete",false}}).dump(2);eventio::Json report={{"schema","rinkfit.same_complete_objective_single_inner_bounded_line_search_probe.v1"},{"source_packet_sha256",b.core.packet.source_hash},{"parent_checkpoint_sha256",eventio::file_sha256(argv[3])},{"parent_state_token",checkpoint.state.token()},{"result_state_token",current.token()},{"line_search_steps",line_steps},{"initial_radius",radius},{"complete_source_E_RS_Query_geometry_W_and_AL_multipliers_same",true},{"solver_max_inner_iterations",1},{"iterations",records},{"timing",timing},{"cache",b.gpu_report()},{"message",result.message},{"native_constraint_or_completion_proof_claimed",false}};std::ofstream rf(out/"report.json");rf<<report.dump(2);std::cout<<report.dump(2);return result.status==InnerStatus::kFailed?2:0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
